previewCss:
.darma-loader-darma-b14-connect-four { --accent: var(--loader-color, #f43f5e); --accent-2: var(--loader-secondary-color, #2563eb); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .92); position: relative; overflow: hidden; border-radius: 6%; background: #0b1220; }
.darma-loader-darma-b14-connect-four::after { content: ''; position: absolute; inset: 0; background: var(--accent-2); -webkit-mask-image: radial-gradient(circle, transparent 0 30%, #000 33%); mask-image: radial-gradient(circle, transparent 0 30%, #000 33%); -webkit-mask-size: 25% 25%; mask-size: 25% 25%; }
.darma-loader-darma-b14-connect-four span { position: absolute; width: calc(var(--loader-size, 108px) * .2); height: calc(var(--loader-size, 108px) * .2); border-radius: 50%; background: radial-gradient(circle at 36% 32%, color-mix(in srgb, #fff 42%, var(--accent)), var(--accent)); animation: darma-loader-darma-b14-connect-four-disc-drop calc(var(--loader-speed, 1s) * 2.7) cubic-bezier(.5, 0, .7, 1) infinite; }
.darma-loader-darma-b14-connect-four span:nth-child(1) { left: 3%; }
.darma-loader-darma-b14-connect-four span:nth-child(2) { left: 28%; background: radial-gradient(circle at 36% 32%, #fff, color-mix(in srgb, #fff 46%, var(--accent))); animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b14-connect-four span:nth-child(3) { left: 53%; animation-delay: calc(var(--loader-speed, 1s) * 1.8); }
@keyframes darma-loader-darma-b14-connect-four-disc-drop { 0% { opacity: 0; top: -24%; } 8% { opacity: 1; } 34% { top: 70%; } 42% { top: 60%; } 50% { top: 70%; } 88% { opacity: 1; top: 70%; } 100% { opacity: 0; top: 70%; } }

